\use strict";
function H(s){var r=[];for(var i=0;i<s.length;i++)r.push(s.charCodeAt(i).toString(16));return r.join(" ")}
function S(v){var t=typeof v;if(t==="string")return "s:"+H(v);if(Array.isArray(v))return "["+v.map(S).join(",")+"]";if(t==="number")return Object.is(v,-0)?"-0":""+v;if(t==="symbol")return "sym";if(t==="bigint")return v+"n";if(v&&t==="object")return "o";return ""+v}
function T(f){try{return S(f())}catch(e){return "throw "+(e&&e.name)+": "+(e&&e.message)}}
globalThis.R = T(()=>"\uAC00".normalize("NFC"))"

